const $=id=>document.getElementById(id),el=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e};
const names={daily:'每日资讯日报',watch:'今日关注',top:'每日 Top 5',spot:'现货上新',perp:'永续合约上新'},states={queued:'已排队',running:'制作／自主审核中',audit_pending:'等待两轮自主复核',retry:'等待重试',failed:'失败待处理',ready:'待审核',approved:'审核通过（未发布）',changes_requested:'需要修改',complete:'来源已保存',expired:'已过期（改用当天数据）'};let rules=[],refreshing=null;const drafts=new Map();
async function api(path,body){
 const r=await fetch('/api/studio'+path+(body?'':(path.includes('?')?'&':'?')+'_fresh='+Date.now()),{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'}),signal:AbortSignal.timeout(path==='/tick'?360000:30000)});
 const d=await r.json().catch(()=>null);if(!r.ok||!d)throw Error(d?.error||'连接失败，请重试（HTTP '+r.status+'）');return d;
}
function action(label,fn){
 const b=el('button',label),note=el('span');note.setAttribute('role','status');note.className='cloud-action-status';
 b.onclick=async()=>{if(b.disabled)return;b.disabled=true;b.setAttribute('aria-busy','true');b.textContent='正在处理…';b.after(note);note.textContent='正在'+label+'…';try{const message=await fn();note.textContent=message||'已完成';}catch(e){note.textContent='未完成：'+e.message;$('cloud-message').textContent=e.message;}finally{b.disabled=false;b.removeAttribute('aria-busy');b.textContent=label;}};return b;
}
async function asset(job){const key=job.asset_key;if(!drafts.has(key)){const pending=api('/asset?id='+encodeURIComponent(job.id)).catch(e=>{drafts.delete(key);throw e});drafts.set(key,pending);if(drafts.size>8)drafts.delete(drafts.keys().next().value);}return drafts.get(key);}
async function refresh(){if(refreshing)return refreshing;refreshing=renderJobs().finally(()=>refreshing=null);return refreshing;}
async function renderJobs(){const d=await api('');rules=d.rules||[];if(d.automationPaused){document.querySelector('#cloud-studio > p').textContent='云端自动制作已暂停。已有稿件和审核记录保留，可以继续使用下方手动制作。';$('cloud-run').disabled=true;}$('cloud-jobs').replaceChildren();const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());const daily=d.jobs.find(j=>j.day===today&&j.type==='daily'&&j.locale==='source');if(daily&&['retry','failed'].includes(daily.state)){$('cloud-jobs').append(el('p','今日日报尚未制作完成：'+daily.error+'。来源恢复前不会生成或发布缺失数据的日报。'));}for(const j of d.jobs){const card=el('article');card.dataset.jobId=j.id;card.style.cssText='border:1px solid #354637;padding:16px;margin:12px 0;border-radius:12px';card.append(el('strong',j.day+' · '+names[j.type]+' · '+(j.locale==='source'?'来源采集':j.locale)+' · '+(states[j.state]||j.state)));if(j.audit_json){try{const rounds=JSON.parse(j.audit_json);if(rounds.length)card.append(el('p',rounds.map(r=>(r.kind==='facts'?'第一轮：数据与 Logo':'第二轮：成图与语言')+' · '+(r.ok?'通过':'未通过')+' · '+new Date(r.checkedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})).join('；')))}catch{}}if(j.error)card.append(el('p',j.error+' · 已尝试 '+j.attempts+' 次 · 下次 '+new Date(j.next_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})));if(j.locale==='source')card.append(action('检查当前云端来源',async()=>{const r=await api('/check-source',{type:j.type});$('cloud-message').textContent=JSON.stringify(r)}));if(j.instruction)card.append(el('p','本次修改指令：'+j.instruction));const sourceDay=j.source_key?.split('/')[2];if(sourceDay&&sourceDay!==j.day)card.append(el('p','历史修订／验收稿 · 原始数据日期 '+sourceDay+'，不代表今天的行情'));if(j.feedback)card.append(el('p','审核意见：'+j.feedback));if(j.asset_key){card.append(action(j.state==='ready'||j.state==='approved'?'查看成品与审核':'查看过程稿与问题',async()=>{if(card.dataset.loaded){card.querySelector('img')?.scrollIntoView({block:'center'});return '成品已展开';}const d=await asset(j),v=d.output;if(!v)throw Error('成品尚未保存');const img=el('img');img.src=v.image;img.alt='云端制作成品';img.style.cssText='max-width:440px;width:100%;display:block';const text=el('textarea');text.value=v.text;text.rows=8;text.readOnly=true;const feedback=el('textarea');feedback.rows=3;feedback.placeholder='给这张图提修改要求或审核意见，像给 Codex 发指令一样';if(!(v.quality?.version===2&&v.quality.ok&&v.quality.rounds?.length===2&&v.quality.rounds.every(r=>r.ok)))card.append(el('p','此版质检未通过：'+(v.quality?.issues||[]).join('；')+'。可查看并提交修改，不能批准发布。'));card.append(action('重新执行两轮自主复核',async()=>{await api('/recheck',{id:j.id});await refresh()}));img.loading='lazy';img.decoding='async';card.append(img,text,feedback,action('保存审核意见 · 暂不重做',async()=>{await api('/review',{id:j.id,state:'changes_requested',feedback:feedback.value});await refresh()}),action('审核通过 · 不发布',async()=>{await api('/review',{id:j.id,state:'approved',feedback:feedback.value});j.state='approved';card.querySelector('strong').textContent=j.day+' · '+names[j.type]+' · '+j.locale+' · 审核通过（未发布）';return '审核已保存，可点击载入发布编辑区';}),action('按指令重新制作 · 保留旧版',async()=>{await api('/revise',{id:j.id,instruction:feedback.value});await refresh()}),action('载入发布编辑区',async()=>{if(v.quality?.version!==2||v.quality.rounds?.length!==2||!v.quality.ok)throw Error('必须先通过两轮自主审核');if(j.state!=='approved')throw Error('请先审核通过，再进入发布区');await new Promise((resolve,reject)=>{window.dispatchEvent(new CustomEvent('studio-load',{detail:{job:j,variant:v,source:d.source,resolve,reject}}));});return '已载入下方发布编辑区，请选择账号与发布时间';}));card.dataset.loaded='1'}))}if(['failed','retry'].includes(j.state))card.append(action('现在重试',async()=>{await api('/retry',{id:j.id});await refresh()}));if(j.state==='failed')card.append(el('p','缺数据或 Logo 无法核实时不会冒充成功。请修正来源后重新制作。'));if(j.state==='expired'||j.source_key?.split('/')[2]&&j.source_key.split('/')[2]!==j.day){const history=el('details');history.append(el('summary','历史／验收记录 · '+j.day+' · '+names[j.type]));history.append(card);$('cloud-jobs').append(history)}else $('cloud-jobs').append(card)}$('cloud-message').textContent=d.automationPaused?'云端自动制作已暂停 · 已有稿件保留':'云端任务已同步 · 不会自动发布'}
$('cloud-refresh').onclick=()=>refresh().catch(e=>$('cloud-message').textContent=e.message);
$('cloud-type').onchange=()=>$('cloud-rule').value=rules.find(r=>r.type===$('cloud-type').value)?.instruction||'';
$('cloud-save-rule').onclick=async()=>{try{await api('/rule',{type:$('cloud-type').value,instruction:$('cloud-rule').value});$('cloud-message').textContent='长期要求已保存，下次制作生效'}catch(e){$('cloud-message').textContent=e.message}};
$('cloud-run').onclick=async()=>{const b=$('cloud-run');b.disabled=true;$('cloud-message').textContent='云端处理中，图片生成可能需要数分钟…';try{const r=await api('/tick',{});await refresh();$('cloud-message').textContent=JSON.stringify(r)}catch(e){$('cloud-message').textContent=e.message}finally{b.disabled=false}};
refresh().catch(e=>$('cloud-message').textContent=e.message);
